public sealed class StatementComposer
{
    private readonly IInvoiceTotalCalculator _totals;
    private readonly IContactResolver _contacts;
    private readonly IAmountFormatter _amounts;

    public StatementComposer(
        IInvoiceTotalCalculator totals,
        IContactResolver contacts,
        IAmountFormatter amounts)
    {
        _totals = totals;
        _contacts = contacts;
        _amounts = amounts;
    }

    public string Build(Account account, IEnumerable<Invoice> invoices)
    {
        var sections = new List<string>
        {
            string.IsNullOrEmpty(account.Name)
                ? "UNKNOWN ACCOUNT"
                : $"STATEMENT FOR {account.Name}",
            $"contact: {_contacts.Resolve(account)}"
